import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { meApi } from '../api/me';
import { CustomerSubscription } from '../types';
import {
  Sparkles,
  Calendar,
  ShieldCheck,
  Clock,
  AlertTriangle,
  CheckCircle2,
  Loader2,
  RefreshCw,
  Info,
  ArrowRight,
} from 'lucide-react';

export const SubscriptionManage: React.FC = () => {
  const [subscriptions, setSubscriptions] = useState<CustomerSubscription[]>([]);
  const [loading, setLoading] = useState(true);
  const [updatingId, setUpdatingId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<string | null>(null);

  const fetchSubscriptions = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await meApi.getSubscriptions();
      setSubscriptions(data);
    } catch (err: any) {
      setError(err?.error || err?.message || 'Could not load subscription entitlements.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSubscriptions();
  }, []);

  const handleToggleCancellation = async (item: CustomerSubscription) => {
    const entitlementId = item.id || item._id;
    if (!entitlementId) return;

    const nextState = !item.cancelAtPeriodEnd;
    setUpdatingId(entitlementId);
    setError(null);
    setFeedback(null);

    try {
      await meApi.updateSubscriptionCancellation(entitlementId, nextState);
      setSubscriptions(prev =>
        prev.map(s =>
          (s.id === entitlementId || s._id === entitlementId)
            ? { ...s, cancelAtPeriodEnd: nextState }
            : s
        )
      );
      setFeedback(
        nextState
          ? 'Cancellation scheduled. Access remains fully active until the end of the current period.'
          : 'Period-end cancellation cancelled. Entitlement will remain active.'
      );
    } catch (err: any) {
      setError(err?.error || err?.message || 'Failed to update cancellation scheduling.');
    } finally {
      setUpdatingId(null);
    }
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-12">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8 pb-6 border-b border-slate-200 dark:border-slate-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-wider text-blue-600 dark:text-blue-400 font-bold">
              PORTFOLIO ACCESS
            </span>
          </div>
          <h1 className="font-display text-2xl sm:text-3xl font-bold text-slate-900 dark:text-white mt-1">
            Manage Subscriptions
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-slate-400 mt-1">
            Active subscription entitlements and term renewal scheduling.
          </p>
        </div>

        <button
          type="button"
          onClick={fetchSubscriptions}
          disabled={loading}
          className="self-start sm:self-auto px-3.5 py-2 rounded-xl border border-slate-200 dark:border-slate-800 hover:bg-slate-100 dark:hover:bg-slate-900 text-xs font-semibold text-slate-700 dark:text-slate-300 inline-flex items-center gap-1.5 transition-colors"
        >
          <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
          <span>Refresh</span>
        </button>
      </div>

      {/* Backend Gap Explicit Flag */}
      <div className="p-4 rounded-2xl bg-slate-100 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 mb-8 flex items-start gap-3 text-xs text-slate-600 dark:text-slate-400 leading-relaxed">
        <Info size={16} className="text-blue-500 shrink-0 mt-0.5" />
        <div>
          <span className="font-semibold text-slate-900 dark:text-white block mb-0.5">
            Architecture Notice — Subscription Lifecycle
          </span>
          Automatic recurring gateway card debits, saved payment method swaps, and mid-cycle pause are not currently supported by the gateway contract. Cancellation scheduling below determines whether your active entitlement concludes cleanly at the end of the current period.
        </div>
      </div>

      {feedback && (
        <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-600 dark:text-emerald-400 text-xs mb-6 flex items-start gap-2.5">
          <CheckCircle2 size={16} className="shrink-0 mt-0.5" />
          <span>{feedback}</span>
        </div>
      )}

      {error && (
        <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-500 text-xs mb-6 flex items-start gap-2.5">
          <AlertTriangle size={16} className="shrink-0 mt-0.5" />
          <span>{error}</span>
        </div>
      )}

      {loading ? (
        <div className="flex flex-col items-center justify-center py-20 text-slate-400">
          <Loader2 size={32} className="animate-spin text-blue-500 mb-3" />
          <span className="text-xs font-mono">Loading subscription entitlements...</span>
        </div>
      ) : subscriptions.length === 0 ? (
        <div className="p-12 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 text-center max-w-md mx-auto">
          <div className="w-14 h-14 rounded-2xl bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-slate-400 mx-auto mb-4">
            <Sparkles size={26} />
          </div>
          <h2 className="font-display text-lg font-bold text-slate-900 dark:text-white mb-2">
            No Active Subscriptions
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mb-6">
            You do not currently have any institutional or individual subscription plans.
          </p>
          <Link
            to="/subscriptions"
            className="inline-flex items-center gap-2 px-5 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-xs font-semibold"
          >
            <span>Explore Plans</span>
          </Link>
        </div>
      ) : (
        <div className="space-y-4">
          {subscriptions.map(item => {
            const entId = item.id || item._id || '';
            const isUpdating = updatingId === entId;
            const isCancelled = Boolean(item.cancelAtPeriodEnd);

            return (
              <div
                key={entId || item.itemId}
                className="p-6 rounded-2xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6"
              >
                <div className="space-y-2">
                  <div className="flex flex-wrap items-center gap-2.5">
                    <span className="font-display text-base font-bold text-slate-900 dark:text-white">
                      {item.itemName || 'Subscription Plan'}
                    </span>
                    <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20">
                      {item.status || 'ACTIVE'}
                    </span>
                    {isCancelled && (
                      <span className="px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 border border-amber-500/20">
                        Cancels At Period End
                      </span>
                    )}
                  </div>

                  <div className="text-xs text-slate-500 dark:text-slate-400 font-mono flex flex-wrap items-center gap-4">
                    <span className="flex items-center gap-1">
                      <Calendar size={12} />
                      <span>Starts: {item.startsAt ? new Date(item.startsAt).toLocaleDateString() : 'Active'}</span>
                    </span>
                    {item.expiresAt && (
                      <span className="flex items-center gap-1 text-slate-400">
                        <Clock size={12} />
                        <span>Term Ends: {new Date(item.expiresAt).toLocaleDateString()}</span>
                      </span>
                    )}
                  </div>
                </div>

                <div className="pt-4 md:pt-0 border-t md:border-t-0 border-slate-100 dark:border-slate-800 flex items-center justify-end gap-3">
                  <button
                    type="button"
                    disabled={isUpdating}
                    onClick={() => handleToggleCancellation(item)}
                    className={`px-4 py-2.5 rounded-xl text-xs font-semibold inline-flex items-center gap-1.5 transition-colors cursor-pointer ${
                      isCancelled
                        ? 'bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-900 dark:text-white'
                        : 'border border-rose-300 dark:border-rose-900/60 text-rose-600 dark:text-rose-400 hover:bg-rose-500/10'
                    }`}
                  >
                    {isUpdating ? (
                      <>
                        <Loader2 size={13} className="animate-spin" />
                        <span>Updating...</span>
                      </>
                    ) : isCancelled ? (
                      <span>Resume Subscription</span>
                    ) : (
                      <span>Schedule Cancellation</span>
                    )}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default SubscriptionManage;
